#!/usr/bin/env bash
# Tags: no-fasttest
# Tag no-fasttest: the `Freeform` format is not built in the fast test.

CUR_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# shellcheck source=../shell_config.sh
. "$CUR_DIR"/../shell_config.sh

# https://github.com/ClickHouse/ClickHouse/pull/110626
# `Freeform` maps a field named by the data by name, but an autogenerated `cN` field to the N-th
# column. A value-level parse error in a positional solution must not get a structure-mismatch
# explanation just because the names `c0`, `c1` are not among the destination columns.

PHRASE="does not match the structure expected by the query"

check() {
    if grep -q "$PHRASE"; then echo "explanation present"; else echo "explanation missing"; fi
}

echo "-- positional fields are read fine"
printf 'CREATE TABLE t (a UInt8, b UInt8) ENGINE = Memory; INSERT INTO t SETTINGS input_format_skip_unknown_fields = 0 FORMAT Freeform\n1 2\n' \
    | $CLICKHOUSE_LOCAL 2>&1 && echo "ok"

echo "-- value parse error in a positional field"
output=$(printf 'CREATE TABLE t (a UInt8, b UInt8) ENGINE = Memory; INSERT INTO t SETTINGS input_format_skip_unknown_fields = 0 FORMAT Freeform\n1 2.5\n' \
    | $CLICKHOUSE_LOCAL 2>&1)
echo "$output" | grep -q 'INCORRECT_DATA' && echo 'parse error' || echo "unexpected: $output"
echo "$output" | check
